sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var sysId = request.pathParams.sys_id;

    // Validate sys_id
    if (!sysId) {
        response.setStatus(400);
        response.setBody({
            success: false,
            error: "sys_id is required"
        });
        return;
    }

    // ServiceNow Incident table
    var gr = new GlideRecord('incident');

    // Validate table
    if (!gr.isValid()) {
        response.setStatus(500);
        response.setBody({
            success: false,
            error: "Incident table is invalid"
        });
        return;
    }

    // Get incident
    if (!gr.get(sysId)) {
        response.setStatus(404);
        response.setBody({
            success: false,
            error: "Incident not found",
            sys_id: sysId
        });
        return;
    }

    var result = {
        sys_id: gr.getUniqueValue(),
        number: gr.getValue('number'),
        short_description: gr.getValue('short_description'),
        description: gr.getValue('description'),
        caller: gr.getDisplayValue('caller_id'),
        category: gr.getValue('category'),
        subcategory: gr.getValue('subcategory'),
        state: gr.getDisplayValue('state'),
        impact: gr.getDisplayValue('impact'),
        urgency: gr.getDisplayValue('urgency'),
        priority: gr.getDisplayValue('priority'),
        assignment_group: gr.getDisplayValue('assignment_group'),
        assigned_to: gr.getDisplayValue('assigned_to'),
        opened_at: gr.getValue('opened_at'),
        updated_at: gr.getValue('sys_updated_on')
    };

    response.setStatus(200);

    response.setBody({
        success: true,
        request: result
    });

})(request, response);
